-- Run on a Spark catalog named `assay`.
CREATE NAMESPACE IF NOT EXISTS assay.repro;
CREATE TABLE assay.repro.t1 (rid BIGINT, k INT, l BIGINT, d DOUBLE, m DECIMAL(18,4), w DECIMAL(38,10), s STRING, dt DATE, ts TIMESTAMP, b BOOLEAN) USING iceberg;
INSERT INTO assay.repro.t1 VALUES (167, 1, CAST(6 AS BIGINT), CAST('NaN' AS DOUBLE), CAST(NULL AS DECIMAL(18,4)), CAST(NULL AS DECIMAL(38,10)), 'b', DATE '2024-01-03', TIMESTAMP '2024-01-01 03:30:00', TRUE);
INSERT INTO assay.repro.t1 VALUES (172, 7, CAST(4 AS BIGINT), CAST(1.7976931348623157E308 AS DOUBLE), CAST(6.5000 AS DECIMAL(18,4)), CAST(0.0000000000 AS DECIMAL(38,10)), 'b', DATE '2024-01-14', TIMESTAMP '2024-01-15 09:30:00', FALSE);
SELECT a1.m AS c1 FROM assay.repro.t1 a0 FULL JOIN assay.repro.t1 a1 ON (a0.d = round(a0.d, pmod(0, 6))) WHERE a1.b;
